        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            arr[i] = (long) in.nval;
        }
        StringBuilder sb = new StringBuilder();
        for (List<Long> c : splitChunks(arr, m)) {
            for (int i = 0; i < c.size(); i++) sb.append(c.get(i)).append(i + 1 < c.size() ? " " : "\n");
        }
        System.out.print(sb);
